const errorData = $input.first().json;

const execution = errorData.execution || {};
const workflow = errorData.workflow || {};
const error = execution.error || {};

const workflowName = workflow.name || 'Unknown Healthcare Workflow';
const workflowId = workflow.id || 'N/A';
const executionId = execution.id || 'N/A';
const nodeName = error.node?.name || 'Unknown Node';
const errorMessage = error.message || 'An unhandled execution error occurred in n8n.';
const timestamp = new Date().toISOString();

return [{
  json: {
    workflowName,
    workflowId,
    executionId,
    nodeName,
    errorMessage,
    timestamp,
    alertMarkdown: `🚨 **n8n Automation Alert: Workflow Failure**\n\n• **Workflow:** ${workflowName} (ID: \`${workflowId}\`)\n• **Failed Node:** \`${nodeName}\`\n• **Execution ID:** \`${executionId}\`\n• **Error Message:** ${errorMessage}\n• **Timestamp:** ${timestamp}\n\n*Please check your n8n console at http://localhost:5678/execution/${executionId} to inspect.*`
  }
}];
